Method.Source:
/// <summary>
/// Finds a record
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <param name = "_update">true or false</param>
/// <returns>Record</returns>
static public NDXMultipleS_SalesQuotation find(InventTable _inventTable, boolean _update = false)
{
    NDXMultipleS_SalesQuotation lNDXMultipleS_SalesQuotation;

    if(_inventTable)
    {
        lNDXMultipleS_SalesQuotation.selectForUpdate(_update);

        select lNDXMultipleS_SalesQuotation
            where lNDXMultipleS_SalesQuotation.RefRecId_InventTable == _inventTable.RecId;
    }

    return lNDXMultipleS_SalesQuotation;
}

/// <summary>
/// Check if chack is available
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <returns>true or false</returns>
static public boolean hasValidityCheck(InventTable _inventTable)
{
    return NDXMultipleS_SalesQuotation::find(_inventTable).RecId > 0;
}

/// <summary>
/// Return all validation sale quotation ids for the item as string
/// </summary>
/// <param name = "_itemRecId">_itemRecId</param>
/// <returns>String of sale quotation ids</returns>
static str Range2String(RecId _itemRecId)
{
    #define.Comma(' ,')

    NDXMultipleS_SalesQuotation       nDX_MultipleS_Quotation;
    SalesQuotationTable lSalesQuotationTable;
    str    range2String;
    boolean             lFirst = true;

    while select nDX_MultipleS_Quotation
        where nDX_MultipleS_Quotation.RefRecId_InventTable == _itemRecId
        join lSalesQuotationTable
            where lSalesQuotationTable.RecId == nDX_MultipleS_Quotation.RefRecId_SalesQuotationTable
    {
        if (!lFirst)
        {
            range2String += #Comma;
        }
        else
        {
            lFirst = false;
        }

        range2String += lSalesQuotationTable.QuotationId;
    }
    return range2String;
}

/// <summary>
/// Writes a log for record change
/// </summary>
/// <param name = "_orig">record before</param>
/// <param name = "_current">record after</param>
private void writeLog(NDXMultipleS_SalesQuotation _orig, NDXMultipleS_SalesQuotation _current)
{
    NDXMultipleS_Log   multipleS_Log;

    if(!_current)
    {
        multipleS_Log.RefRecIdInventTable = _orig.RefRecId_InventTable;
    }
    else
    {
        multipleS_Log.RefRecIdInventTable = _current.RefRecId_InventTable;
    }

    if (_orig.RefRecId_SalesQuotationTable != _current.RefRecId_SalesQuotationTable)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::QuotationNumber;

        multipleS_Log.RangeValue        =  SalesQuotationTable::findRec(_current.RefRecId_SalesQuotationTable).QuotationId;

        if (!_orig.RefRecId_SalesQuotationTable)            // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.RefRecId_SalesQuotationTable) // Löschung
        {
            multipleS_Log.RangeValue        = SalesQuotationTable::findRec(_orig.RefRecId_SalesQuotationTable).QuotationId;
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                                // Änderung
        {
            multipleS_Log.RangeValue        += strFmt("@ApplicationFoundation:DocuDeletedRefCaptionGeneratorFromLabel", SalesQuotationTable::findRec(_orig.RefRecId_SalesQuotationTable).QuotationId);
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

}

public void insert()
{
    NDXMultipleS_SalesQuotation orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void update()
{
    NDXMultipleS_SalesQuotation orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void delete()
{
    NDXMultipleS_SalesQuotation orig = this.orig();
    super();
    this.writeLog(orig, null);
}
